package com.primehr.security;
import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class LdFoundationPermissionGuardTest {
 @Test void actionsAndAgencyScopeFailClosed(){AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);LdFoundationPermissionGuard guard=new LdFoundationPermissionGuard(client);when(client.resolve(LdFoundationPermissionGuard.GOVERNANCE,"Bearer token")).thenReturn(permission(true,true,false,true,PermissionDataScope.AGENCY_WIDE));when(client.resolve(LdFoundationPermissionGuard.PROGRAM,"Bearer token")).thenReturn(permission(true,false,true,false,PermissionDataScope.OWN_RECORDS));assertThatCode(()->guard.require(LdFoundationPermissionGuard.GOVERNANCE,PrimeHrAction.PUBLISH,"Bearer token")).doesNotThrowAnyException();assertThatThrownBy(()->guard.require(LdFoundationPermissionGuard.GOVERNANCE,PrimeHrAction.EDIT,"Bearer token")).isInstanceOf(AccessDeniedException.class);assertThatThrownBy(()->guard.require(LdFoundationPermissionGuard.PROGRAM,PrimeHrAction.EDIT,"Bearer token")).isInstanceOf(AccessDeniedException.class);}
 private EffectiveFeaturePermission permission(boolean access,boolean add,boolean edit,boolean publish,PermissionDataScope scope){return new EffectiveFeaturePermission("feature",false,access,add,edit,false,publish,false,false,false,false,false,scope);}
}
